"""Runtime support for vecDSL programs generated for MongoDB, through PyMongo. Generated by vecDSL 7. Do not edit.

Every command document, index definition, filter and aggregation pipeline is built by the generator and arrives here as a
value identical in the Python, TypeScript and Java programs; this module sends it with Database.command or
Collection.aggregate and shapes the answer. Numbers are sent in one BSON form in every language (integral values as int32,
or int64 beyond its range, others as double; vectors always as doubles). Search results are eventually consistent: mongot
follows mongod through a change stream, so a write that asks for visibility waits until every search index of its
collection shows it. The result-shape clauses that MongoDB has no stage for (boost and mmr, and the result clauses of a hybrid
search) run in the shared module vecdsl_shapes over the candidate window.
"""

from __future__ import annotations

import json
import math
import os
import re
import time
import uuid
from datetime import datetime, timedelta, timezone
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence

import vecdsl_shapes

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 500
_POLL_SECONDS = 0.25
_INT32 = 2 ** 31
_STAMP = "vecdsl_stamp"
_VERSION = "vecdsl_version"
_EXPIRES = "vecdsl_expires"
_MAJORITY = {"w": "majority"}


class Double(float):
    """A number sent as a BSON double even when it is integral (vector components)."""


class UnsupportedFeature(NotImplementedError):
    pass


class MongodbFailure(RuntimeError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

from bson import Decimal128, Int64, ObjectId  # noqa: E402
from pymongo import MongoClient  # noqa: E402
from pymongo.errors import OperationFailure, PyMongoError  # noqa: E402
from pymongo.read_concern import ReadConcern  # noqa: E402
from pymongo.write_concern import WriteConcern  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


class Client:
    """The MongoClient of one program; credentials come from the environment only."""

    def __init__(self, url: str, user: str | None, user_variable: str, password_variable: str, timeout_seconds: float) -> None:
        if "@" in url.split("//", 1)[-1].split("/", 1)[0]:
            raise ValueError("the MongoDB URI must not contain credentials; set them in the environment")
        self.url = url
        self.timeout_seconds = timeout_seconds
        millis = int(timeout_seconds * 1000)
        options: dict[str, Any] = {"serverSelectionTimeoutMS": millis, "connectTimeoutMS": millis, "socketTimeoutMS": millis,
                                   "appname": "vecdsl"}
        name = os.environ.get(user_variable) or user
        if name:
            password = os.environ.get(password_variable)
            if password is None:
                raise KeyError(f"environment variable {password_variable} is not set (the password of user {name})")
            options.update(username=name, password=password, authSource="admin")
        self.mongo: MongoClient = MongoClient(url, **options)

    def close(self) -> None:
        self.mongo.close()


def connect(url: str, user: str | None = None, user_variable: str = "VECDSL_MONGODB_USER",
            password_variable: str = "VECDSL_MONGODB_PASSWORD", timeout_seconds: float = 30) -> Client:
    return Client(url, user, user_variable, password_variable, timeout_seconds)


def _date(text: str) -> datetime:
    value = datetime.fromisoformat(text.replace("Z", "+00:00"))
    return value if value.tzinfo else value.replace(tzinfo=timezone.utc)


def _bson(value: Any) -> Any:
    """A value in the BSON form every runtime sends: integral numbers as int32 (int64 beyond), others as double, {"$date": ISO} as a date."""
    if isinstance(value, (bool, str, datetime, ObjectId, Double)) or value is None:
        return value
    if isinstance(value, float) and value.is_integer() and math.isfinite(value) and abs(value) < 1e15:
        value = int(value)
    if isinstance(value, int):
        return value if -_INT32 <= value < _INT32 else Int64(value)
    if isinstance(value, dict):
        if len(value) == 1 and isinstance(value.get("$date"), str):
            return _date(value["$date"])
        return {str(key): _bson(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_bson(item) for item in value]
    return value


def _doubles(vector: Any) -> Any:
    return None if vector is None else [Double(item) for item in vector]


def _geo(value: Any) -> Any:
    """GeoJSON points from {"$geoPoint": "lat,lon"} (a geo_point value of the script) and from {"lat": ..., "lon": ...} records."""
    if isinstance(value, dict) and list(value) == ["$geoPoint"]:
        text = value["$geoPoint"]
        parts = text.split(",") if isinstance(text, str) else []
        try:
            latitude, longitude = (float(part) for part in parts)
        except ValueError:
            raise MongodbFailure(f'a geo_point value is written "lat,lon", not {text!r}') from None
        return {"type": "Point", "coordinates": [Double(longitude), Double(latitude)]}
    if isinstance(value, dict) and "lat" in value and ("lon" in value or "lng" in value):
        return {"type": "Point", "coordinates": [Double(value.get("lon", value.get("lng"))), Double(value["lat"])]}
    return value


def _coerce(document: dict[str, Any], vectors: Sequence[str] | None, dates: Sequence[str] | None) -> dict[str, Any]:
    result = _bson(document)
    for name in vectors or ():
        if result.get(name) is not None:
            result[name] = _doubles(result[name])
    for name in dates or ():
        if isinstance(result.get(name), str):
            result[name] = _date(result[name])
    for name, item in list(result.items()):
        result[name] = _geo(item)
    return result


def _iso(value: datetime) -> str:
    utc = value.astimezone(timezone.utc) if value.tzinfo else value.replace(tzinfo=timezone.utc)
    return utc.strftime("%Y-%m-%dT%H:%M:%S.") + f"{utc.microsecond // 1000:03d}Z"


def _value(value: Any, rounded: bool = True) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers, dates as ISO strings;
    without rounded, the floats as they are (the candidates of the shared result-shape module, which rounds once)."""
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, Int64):
        return int(value)
    if isinstance(value, Decimal128):
        value = float(value.to_decimal())
    if isinstance(value, float):
        if not rounded:
            return value
        value = round(value, _DIGITS)
        return int(value) if value.is_integer() else value
    if isinstance(value, datetime):
        return _iso(value)
    if isinstance(value, ObjectId):
        return str(value)
    if isinstance(value, list):
        return [_value(item, rounded) for item in value]
    if isinstance(value, dict):
        return {key: _value(item, rounded) for key, item in value.items()}
    return value


def _record(document: dict[str, Any], key: str | None) -> dict[str, Any]:
    """A record with the key first and the score second, as every runtime orders them."""
    if key is None or key not in document:
        return document
    ordered = {key: document[key]}
    if "score" in document:
        ordered["score"] = document["score"]
    ordered.update((name, item) for name, item in document.items() if name not in ordered)
    return ordered


def _failure(error: PyMongoError, what: str) -> MongodbFailure:
    if isinstance(error, OperationFailure):
        details = error.details or {}
        return MongodbFailure(f"{what} failed: {details.get('codeName', error.code)}: {details.get('errmsg', str(error))}")
    return MongodbFailure(f"{what} failed ({type(error).__name__}): {error}")


def _command(client: Client, database: str, document: dict[str, Any], session: Any = None) -> dict[str, Any]:
    try:
        return client.mongo[database].command(_bson(document), session=session)
    except PyMongoError as error:
        raise _failure(error, f"{next(iter(document))} on {database}") from error


def _select(value: Any, path: Sequence[str] | None) -> Any:
    for key in path or ():
        if value is None:
            return None
        if isinstance(value, list):
            index = int(key)
            value = value[index] if index < len(value) else None
        else:
            value = value.get(key)
    return value


def command(client: Client, database: str, command: dict[str, Any], select: Sequence[str] | None = None, wrap: str | None = None,
            ignore: Sequence[str] = ()) -> Any:
    """One database command; select picks a member of the answer, wrap names it, ignore lists error code names that mean done."""
    try:
        answer = client.mongo[database].command(_bson(command))
    except OperationFailure as error:
        if (error.details or {}).get("codeName") in ignore:
            return None
        raise _failure(error, f"{next(iter(command))} on {database}") from error
    except PyMongoError as error:
        raise _failure(error, f"{next(iter(command))} on {database}") from error
    result = _value(_select(answer, select))
    return {wrap: result} if wrap is not None else result


def exists(client: Client, database: str, collection: str) -> bool:
    answer = _command(client, database, {"listCollections": 1, "filter": {"name": {"$eq": collection}}, "nameOnly": True})
    return bool(answer["cursor"]["firstBatch"])


def _query_vectors(pipeline: Sequence[dict[str, Any]], vector: Sequence[float] | None = None) -> list[dict[str, Any]]:
    """The pipeline with every $vectorSearch queryVector as doubles (vector replaces it when given)."""
    result = []
    for stage in pipeline:
        stage = dict(stage)
        if "$vectorSearch" in stage:
            search = dict(stage["$vectorSearch"])
            search["queryVector"] = _doubles(vector if vector is not None else search["queryVector"])
            stage["$vectorSearch"] = search
        elif "$rankFusion" in stage:
            fusion = json.loads(json.dumps(stage["$rankFusion"]))
            for name, inner in fusion["input"]["pipelines"].items():
                fusion["input"]["pipelines"][name] = _query_vectors(inner)
            stage["$rankFusion"] = fusion
        result.append(stage)
    return result


def _aggregate(client: Client, database: str, collection: str, pipeline: Sequence[dict[str, Any]],
               options: dict[str, Any] | None = None, session: Any = None) -> list[dict[str, Any]]:
    try:
        return list(client.mongo[database][collection].aggregate(_bson(_query_vectors(pipeline)), session=session, **(options or {})))
    except PyMongoError as error:
        raise _failure(error, f"aggregate on {database}.{collection}") from error


def aggregate(client: Client, database: str, collection: str, pipeline: Sequence[dict[str, Any]], key: str | None = None,
              options: dict[str, Any] | None = None, first: bool = False, select: Sequence[str] | None = None, default: Any = None,
              candidates: bool = False) -> Any:
    """A pipeline; its documents as records (key first, score second), or the first document, or a member of it; with
    candidates, the records unrounded for the shared result-shape module (see shape)."""
    documents = [_record(document, key) for document in _aggregate(client, database, collection, pipeline, options)]
    if candidates:
        return _value(documents, False)
    if not first:
        return _value(documents)
    result = _select(documents[0], select) if documents else None
    return _value(default if result is None else result)


def ensure_search_index(client: Client, database: str, collection: str, index: str, type: str, definition: dict[str, Any]) -> None:
    """Creates the search index, or updates its definition when it exists."""
    existing = _aggregate(client, database, collection, [{"$listSearchIndexes": {"name": index}}])
    if existing:
        _command(client, database, {"updateSearchIndex": collection, "name": index, "definition": definition})
    else:
        _command(client, database, {"createSearchIndexes": collection, "indexes": [{"name": index, "type": type, "definition": definition}]})


def await_index(client: Client, database: str, collection: str, index: str, timeout_seconds: float) -> str:
    """The status of a search index once it is READY and queryable, or a clear error after timeout_seconds."""
    deadline = time.monotonic() + timeout_seconds
    status = "missing"
    while True:
        found = _aggregate(client, database, collection, [{"$listSearchIndexes": {"name": index}}])
        if found:
            status = found[0].get("status", "UNKNOWN")
            if status == "FAILED":
                raise MongodbFailure(f"search index {index} on {database}.{collection} failed to build: {found[0].get('message', '')}")
            if status == "READY" and found[0].get("queryable"):
                return status
        if time.monotonic() >= deadline:
            raise TimeoutError(f"search index {index} on {database}.{collection} was not queryable within {timeout_seconds} seconds (status {status})")
        time.sleep(_POLL_SECONDS)


def _probe(probe: dict[str, Any], condition: dict[str, Any], limit: int) -> list[dict[str, Any]]:
    if probe["kind"] == "vector":
        query = [1.0] + [0.0] * (int(probe["dims"]) - 1)
        return [{"$vectorSearch": {"index": probe["index"], "path": probe["path"], "queryVector": query, "exact": True, "limit": max(1, limit),
                                   "filter": condition}}, {"$count": "n"}]
    if "_id" in condition:
        operator: dict[str, Any] = {"in": {"path": "_id", "value": condition["_id"]["$in"]}}
    else:
        operator = {"equals": {"path": _STAMP, "value": condition[_STAMP]["$eq"]}}
    return [{"$search": {"index": probe["index"], **operator}}, {"$count": "n"}]


def _visible(client: Client, database: str, collection: str, visible: dict[str, Any] | None, stamp: str | None = None,
             deleted: Sequence[Any] | None = None) -> None:
    """Waits until mongot shows the write in every search index: the stamped documents, or the deleted keys gone."""
    if not visible:
        return
    timeout = float(visible["timeout_seconds"])
    deadline = time.monotonic() + timeout
    for probe in visible["probes"]:
        if deleted is not None:
            condition: dict[str, Any] = {"_id": {"$in": list(deleted)}}
            expected = 0
        else:
            condition = {_STAMP: {"$eq": stamp}}
            stored: dict[str, Any] = dict(condition)
            if probe["kind"] == "vector":
                stored[probe["path"]] = {"$type": "array"}
            counted = _aggregate(client, database, collection, [{"$match": stored}, {"$count": "n"}])
            expected = counted[0]["n"] if counted else 0
        if deleted is not None and not deleted:
            continue
        while True:
            found = _aggregate(client, database, collection, _probe(probe, condition, max(expected, len(deleted or ()))))
            count = found[0]["n"] if found else 0
            if (deleted is not None and count == 0) or (deleted is None and count >= expected):
                break
            if time.monotonic() >= deadline:
                raise TimeoutError(f"search index {probe['index']} of {database}.{collection} did not show the write within {timeout} seconds")
            time.sleep(_POLL_SECONDS)


def _documents(records: Sequence[dict[str, Any]], key: str, extra: dict[str, Any] | None, defaults: dict[str, Any] | None,
               vectors: Sequence[str] | None, dates: Sequence[str] | None, versioned: bool, ttl_seconds: float | None, stamp: str) -> list[dict[str, Any]]:
    documents = []
    expires = datetime.now(timezone.utc) + timedelta(seconds=ttl_seconds) if ttl_seconds is not None else None
    for record in records:
        if key not in record:
            raise MongodbFailure(f"a record without the key {key}: {json.dumps(record, default=str)[:200]}")
        body = {**(defaults or {}), **{name: item for name, item in record.items() if name != key}, **(extra or {})}
        document = {"_id": record[key], **_coerce(body, vectors, dates), _STAMP: stamp}
        if versioned:
            document[_VERSION] = 1
        if expires is not None:
            document[_EXPIRES] = expires
        documents.append(_bson(document))
    return documents


def _write_documents(client: Client, database: str, collection: str, documents: list[dict[str, Any]], op: str, batch_size: int,
                     ignore_conflicts: bool, session: Any = None) -> tuple[int, int]:
    written = skipped = 0
    concern = {} if session is not None else {"writeConcern": _MAJORITY}
    for start in range(0, len(documents), batch_size):
        batch = documents[start:start + batch_size]
        if op == "insert":
            answer = _command(client, database, {"insert": collection, "documents": batch, "ordered": not ignore_conflicts, **concern}, session)
        elif op == "patch":
            updates = [{"q": {"_id": {"$eq": document["_id"]}},
                        "u": {"$set": {name: item for name, item in document.items() if name not in ("_id", _VERSION)},
                              **({"$inc": {_VERSION: 1}} if _VERSION in document else {})},
                        "upsert": False} for document in batch]
            answer = _command(client, database, {"update": collection, "updates": updates, "ordered": True, **concern}, session)
        else:
            updates = [{"q": {"_id": {"$eq": document["_id"]}},
                        "u": {"$set": {name: item for name, item in document.items() if name != "_id"}} if op == "merge"
                        else {name: item for name, item in document.items() if name != "_id"},
                        "upsert": True} for document in batch]
            answer = _command(client, database, {"update": collection, "updates": updates, "ordered": True, **concern}, session)
        errors = answer.get("writeErrors", [])
        for error in errors:
            if error.get("code") == 11000 and ignore_conflicts:
                skipped += 1
            else:
                raise MongodbFailure(f"{op} into {database}.{collection} failed: {error.get('code')}: {error.get('errmsg')}")
        written += answer.get("n", 0)
    return written, skipped


def write(client: Client, database: str, collection: str, records: Sequence[dict[str, Any]], key: str, op: str, counter: str,
          extra: dict[str, Any] | None = None, defaults: dict[str, Any] | None = None, vectors: Sequence[str] | None = None,
          dates: Sequence[str] | None = None, versioned: bool = False, ttl_seconds: float | None = None, batch_size: int = _BATCH,
          ignore_conflicts: bool = False, visible: dict[str, Any] | None = None, session: Any = None,
          only: Sequence[Any] | None = None) -> dict[str, int]:
    """Records written as insert commands (insert), or update commands with upsert: a replacement (replace) or $set (merge), or
    without upsert (patch: $set on existing documents only; a missing document is not counted). With only, the records whose key
    is not among those keys are left out."""
    if only is not None:
        keys = {json.dumps(value, default=str) for value in only}
        records = [record for record in records if key in record and json.dumps(record[key], default=str) in keys]
    stamp = uuid.uuid4().hex
    documents = _documents(records, key, extra, defaults, vectors, dates, versioned, ttl_seconds, stamp)
    written, skipped = _write_documents(client, database, collection, documents, op, batch_size, ignore_conflicts, session)
    if skipped and not ignore_conflicts:
        raise MongodbFailure(f"{skipped} records of the insert into {database}.{collection} already exist")
    if session is None:
        _visible(client, database, collection, visible, stamp)
    result = {counter: written, "skipped": skipped} if ignore_conflicts else {counter: written}
    return {**result, "_stamp": stamp} if session is not None else result


def update(client: Client, database: str, collection: str, filter: dict[str, Any], update: dict[str, Any], counter: str = "update_count",
           vectors: Sequence[str] | None = None, dates: Sequence[str] | None = None, visible: dict[str, Any] | None = None,
           session: Any = None) -> dict[str, Any]:
    """An update command on every matching document; values are operands of $set, $unset, $push, $pull and $inc."""
    stamp = uuid.uuid4().hex
    change = {operator: dict(fields) for operator, fields in update.items()}
    change["$set"] = {**_coerce(change.get("$set", {}), vectors, dates), _STAMP: stamp}
    concern = {} if session is not None else {"writeConcern": _MAJORITY}
    answer = _command(client, database, {"update": collection, "updates": [{"q": filter, "u": change, "multi": True}], **concern}, session)
    for error in answer.get("writeErrors", []):
        raise MongodbFailure(f"update of {database}.{collection} failed: {error.get('code')}: {error.get('errmsg')}")
    if session is None:
        _visible(client, database, collection, visible, stamp)
    result: dict[str, Any] = {counter: answer.get("n", 0)}
    return {**result, "_stamp": stamp} if session is not None else result


def delete(client: Client, database: str, collection: str, filter: dict[str, Any], limit: int | None = None,
           visible: dict[str, Any] | None = None, session: Any = None) -> dict[str, Any]:
    """A delete command; a limit above 1 (or a wait for mongot) first reads the matching keys in key order."""
    keys = None
    if (limit is not None and limit > 1) or visible:
        stages: list[dict[str, Any]] = [{"$match": filter}, {"$sort": {"_id": 1}}]
        if limit is not None:
            stages.append({"$limit": limit})
        stages.append({"$project": {"_id": 1}})
        keys = [document["_id"] for document in _aggregate(client, database, collection, stages, session=session)]
        filter = {"_id": {"$in": keys}}
    concern = {} if session is not None else {"writeConcern": _MAJORITY}
    answer = _command(client, database, {"delete": collection, "deletes": [{"q": filter, "limit": 1 if limit == 1 else 0}], **concern}, session)
    if session is None:
        _visible(client, database, collection, visible, deleted=keys)
    result: dict[str, Any] = {"delete_count": answer.get("n", 0)}
    return {**result, "_deleted": keys} if session is not None else result


def transaction(client: Client, steps: Sequence[dict[str, Any]], read_concern: str = "snapshot") -> list[Any]:
    """The steps' writes in one multi-document transaction (aborted on any error); waits for mongot after the commit."""
    operations = {"write": write, "update": update, "delete": delete}
    results: list[Any] = []
    with client.mongo.start_session() as session:
        session.start_transaction(read_concern=ReadConcern(read_concern), write_concern=WriteConcern("majority"))
        try:
            for step in steps:
                results.append(operations[step["op"]](client, **step["args"], session=session))
            session.commit_transaction()
        except Exception:
            if session.in_transaction:
                session.abort_transaction()
            raise
    shaped = []
    for step, result in zip(steps, results):
        args = step["args"]
        stamp = result.pop("_stamp", None)
        deleted = result.pop("_deleted", None)
        if args.get("visible"):
            if step["op"] == "delete":
                _visible(client, args["database"], args["collection"], args["visible"], deleted=deleted or [])
            else:
                _visible(client, args["database"], args["collection"], args["visible"], stamp)
        shaped.append(result)
    return _value(shaped)


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, location: str, database: str, collection: str, key: str, op: str, counter: str,
                extra: dict[str, Any] | None = None, defaults: dict[str, Any] | None = None, vectors: Sequence[str] | None = None,
                dates: Sequence[str] | None = None, versioned: bool = False, batch_size: int = _BATCH, ignore_conflicts: bool = False) -> dict[str, int]:
    return write(client, database, collection, read_records(client, location), key, op, counter, extra, defaults, vectors, dates,
                 versioned, None, batch_size, ignore_conflicts)


def names(client: Client, kind: str, database: str, collection: str | None = None, field: str | None = None, prefix: str | None = None,
          limit: int | None = None) -> list[str]:
    """Names: collections, views, databases, search indexes or the distinct values of a field."""
    if kind == "collections":
        batch = _command(client, database, {"listCollections": 1, "filter": {"type": "collection"}, "nameOnly": True})["cursor"]["firstBatch"]
        found = [entry["name"] for entry in batch if not entry["name"].startswith("system.")]
    elif kind == "views":
        batch = _command(client, database, {"listCollections": 1, "filter": {"type": "view"}})["cursor"]["firstBatch"]
        found = [entry["name"] for entry in batch if collection is None or entry.get("options", {}).get("viewOn") == collection]
    elif kind == "databases":
        found = [entry["name"] for entry in _command(client, "admin", {"listDatabases": 1, "nameOnly": True})["databases"]
                 if entry["name"] not in ("admin", "config", "local")]
    elif kind == "search_indexes":
        found = [entry["name"] for entry in _aggregate(client, database, str(collection), [{"$listSearchIndexes": {}}])]
    else:
        found = [str(_value(item)) for item in _command(client, database, {"distinct": collection, "key": field, "query": {}})["values"] if item is not None]
    found = sorted(set(found))
    if prefix is not None:
        found = [name for name in found if name.startswith(prefix)]
    return found[:limit] if limit is not None else found


def _vectors(client: Client, database: str, collection: str, field: str, values: Sequence[Any]) -> list[list[float]]:
    if not values:
        return []
    found = {json.dumps(_value(document["_id"])): document.get(field) for document in
             _aggregate(client, database, collection, [{"$match": {"_id": {"$in": list(values)}}}, {"$project": {field: 1}}])}
    vectors = [found.get(json.dumps(_value(_bson(value)))) for value in values]
    if any(vector is None for vector in vectors):
        raise MongodbFailure(f"an example of the recommendation has no {field} vector in {database}.{collection}")
    return vectors


def _average(vectors: Sequence[Sequence[float]]) -> list[float]:
    return [sum(column) / len(vectors) for column in zip(*vectors)]


def recommend(client: Client, database: str, collection: str, lookup: str, field: str, pipeline: Sequence[dict[str, Any]], key: str,
              options: dict[str, Any] | None = None, first: bool = False, positive_ids: Sequence[Any] = (),
              positive_vectors: Sequence[Sequence[float]] = (), negative_ids: Sequence[Any] = (),
              negative_vectors: Sequence[Sequence[float]] = (), candidates: bool = False) -> Any:
    """Qdrant's average-vector strategy: avg(positive) + (avg(positive) - avg(negative)) as the queryVector of $vectorSearch;
    with candidates, the records unrounded for the shared result-shape module (see shape)."""
    positives = [*_vectors(client, database, lookup, field, positive_ids), *positive_vectors]
    negatives = [*_vectors(client, database, lookup, field, negative_ids), *negative_vectors]
    query = _average(positives)
    if negatives:
        avoid = _average(negatives)
        query = [2 * p - n for p, n in zip(query, avoid)]
    documents = [_record(document, key) for document in
                 _aggregate(client, database, collection, _query_vectors(pipeline, query), options)]
    if candidates:
        return _value(documents, False)
    return _value(documents[0] if first and documents else documents)


def _order(record: dict[str, Any], key: str) -> tuple[Any, ...]:
    value = record[key]
    return (-record["score"], 0, value, "") if isinstance(value, (int, float)) else (-record["score"], 1, 0, str(value))


def _within(score: float, bounds: dict[str, float] | None) -> bool:
    if not bounds:
        return True
    return (bounds.get("min") is None or score >= bounds["min"] - 1e-9) and (bounds.get("max") is None or score <= bounds["max"] + 1e-9)


def hybrid(client: Client, database: str, collection: str, legs: Sequence[dict[str, Any]], fusion: str, k: int, size: int, offset: int,
           key: str, bounds: dict[str, float] | None = None, candidates: bool = False) -> list[Any]:
    """Fusion of the legs' records: rrf sums 1/(k + rank), weighted sums weight * similarity, relative_score sums the
    weighted min-max normalized similarities; ties by key. With candidates, the fused records come back unrounded for the
    shared result-shape module (see shape)."""
    fused: dict[str, dict[str, Any]] = {}
    for leg in legs:
        hits = [_record(document, key) for document in _aggregate(client, database, collection, leg["pipeline"])]
        scores = [hit["score"] for hit in hits]
        low, high = (min(scores), max(scores)) if scores else (0.0, 0.0)
        for rank, hit in enumerate(hits, start=1):
            if fusion == "rrf":
                part = 1 / (k + rank)
            elif fusion == "relative_score":
                part = leg["weight"] * ((hit["score"] - low) / (high - low) if high > low else 1.0)
            else:
                part = leg["weight"] * hit["score"]
            entry = fused.setdefault(json.dumps(_value(hit[key])), {**{name: item for name, item in hit.items() if name != "score"}, "score": 0.0})
            entry["score"] += part
    ranked = sorted((record for record in fused.values() if _within(record["score"], bounds)), key=lambda record: _order(record, key))
    return _value([_record(record, key) for record in ranked[offset:offset + size]], not candidates)


def shape(client: Client, candidates: Sequence[dict[str, Any]], spec: dict[str, Any], vectors: Sequence[str]) -> Any:
    """The result-shape clauses over a candidate window, by the shared module vecdsl_shapes: each record becomes a candidate
    {key, score, fields, vectors, highlight, explanation} (its highlights as the highlight); the vector fields the candidates
    carry go to vectors and stay among the fields only where the output names them."""
    key = spec["keyField"]
    listed = set(spec.get("output") or ())
    items = []
    for record in candidates:
        item: dict[str, Any] = {
            "key": record[key], "score": record.get("score"),
            "fields": {name: value for name, value in record.items()
                       if name not in (key, "score", "highlights", "explanation") and (name not in vectors or name in listed)},
            "vectors": {name: record[name] for name in vectors if name in record}}
        if "highlights" in record:
            item["highlight"] = record["highlights"]
        if "explanation" in record:
            item["explanation"] = record["explanation"]
        items.append(item)
    try:
        return vecdsl_shapes.shape(items, spec)
    except vecdsl_shapes.UnsupportedShape as error:
        unsupported("mongodb", str(error))
